#!/usr/bin/env python3
"""Verify final RAM7 image/check ties and write reviewable bundle metadata."""
from pathlib import Path
import hashlib,json,zlib
r=Path(__file__).resolve().parent;e=r/'evidence';assert not (r/'c80-openwrt-ram7-query.zip').exists()
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
log=(r/'verification-core.log').read_text();assert 'PASS:99' in log
assert len([x for x in log.splitlines() if x.startswith('PASS ')])==99
assert json.loads((e/'stock-download-traces.json').read_text())['cases_passed']==23
assert json.loads((e/'stock-main-traces.json').read_text())['cases_passed']==27
assert len(json.loads((e/'rootfs-elf-closure.json').read_text()))==57
fw=json.loads((r/'FIRMWARE-SOURCES.json').read_text());assert len(fw['files'])==6
qemu={}
for mode in ('missing-firmware','aon-refusal'):
 q=json.loads((e/f'qemu-{mode}-result.json').read_text());assert q['passed']
 assert sha(r/'build/usr/initramfs_data.cpio')==q['rootfs_cpio_sha256']
 assert sha(r/'build-qemu/arch/arm/boot/zImage')==q['qemu_kernel_sha256']
 qemu[mode]=len(q['commands'])
 if mode=='aon-refusal':assert q['normal_reboot_and_C80_callback_before_PSCI_fallback']
assert 'All twenty files match' in (r/'artifacts/patch-verification.txt').read_text()
assert json.loads((e/'ram6-change-scope.json').read_text())['passed']
assert json.loads((e/'stock-dma-mode-traces.json').read_text())['cases_passed']==15
assert json.loads((e/'stock-query-traces.json').read_text())['cases_passed']==8
restart=json.loads((e/'restart-result.json').read_text());assert restart['passed'] and restart['cases_passed']==8
assert restart['Linux_vmlinux_sha256']==sha(r/'build/vmlinux')
decompressor=json.loads((e/'decompressor-result.json').read_text());assert decompressor['passed']
assert decompressor['zimage_sha256']==sha(r/'c80-openwrt-ram7-query-zImage') and len(decompressor['checks'])==6
handoff=json.loads((e/'handoff-verification.json').read_text());assert len(handoff['cases'])==5 and all(x['status']=='pass' for x in handoff['cases'])
assert handoff['payload_sha256']==sha(r/'c80-openwrt-ram7-handoff.bin')
records=[]
for address,name in ((0x41000000,'c80-openwrt-ram7-query-zImage'),(0x40f00000,'c80-openwrt-ram7-query.dtb'),(0x40e00000,'c80-openwrt-ram7-handoff.bin')):
 data=(r/name).read_bytes();records.append({'file':name,'address':hex(address),'bytes':len(data),'crc32':f'{zlib.crc32(data):08x}','sha256':sha(r/name)})
assert (r/'c80-openwrt-ram7-query-zImage').read_bytes()==(r/'build/arch/arm/boot/zImage').read_bytes()
assert (r/'c80-openwrt-ram7-query.dtb').read_bytes()==(r.parent/'openwrt-ram4-patch/c80-openwrt-ram4-patch.dtb').read_bytes()
assert (r/'c80-openwrt-ram7-handoff.bin').read_bytes()==(r.parent/'openwrt-ram4-patch/c80-openwrt-ram4-handoff.bin').read_bytes()
assert (r/'c80-script-runner.bin').stat().st_size==4732
lines=[x for x in (r/'c80-start.txt').read_text().splitlines() if not x.startswith('#')];assert len(lines)==6 and lines[0]=='C80SCRIPT1' and lines[-2]=='go 40e00000'
for row in records:assert f"load {int(row['address'],16):08x} {row['file']} {row['bytes']:08x} {row['crc32']}" in lines
p={'kernel':'6.12.113-c80-openwrt-ram7-query','userspace':'OpenWrt25.12.5 r33051-f5dae5ece4; unchanged35packages/57ELF','load_files':records,'script_bytes':(r/'c80-start.txt').stat().st_size,'hardware_tested':False,'parent_physical_main_download_start_state3_passed':True,'physical_runtime_query_tested':False,'parent_RAM4_patch_download_readiness_and_cleanup_passed':True,'parent_software_reboot_after_MCU_confirmed':True,'parent_RAM6_main_result':{'primary':0,'payload_completed_bytes':25616,'start_attempted':1,'main_ready':1,'cleanup':1,'critical':0,'mask_after':'20000000'},'download_mode':{'register':'0x18004208','mask':'0x200','OEM_callback':'0x40308dd0','command_ring_retained':15,'scatter_ring_retained':3,'parent_full_download_with_mode_passed':True,'runtime_mode_off_hardware_unproven':True},'scope':'Runtime GET counter after verified main/start/state3, explicit zero IRQ mask restoration; exact supplied WIFI_RAM_CODE_7626.bin after patch, 3 regions/25616 payload bytes/29fragments, start flags0/address0 then sync state3; no AP/RF/IRQ-enable/NOR commands','main_firmware':{'file':'WIFI_RAM_CODE_7626.bin','bytes':25808,'CRC32':'92c09901','SHA256':'76a9a4fb62be68725fba016d0814911255cf62b819d41760198dc7e3911322b5','regions':[{'MCU_address':'0x20400','bytes':2896,'chunks':4},{'MCU_address':'0x2010000','bytes':1584,'chunks':2},{'MCU_address':'0x40100000','bytes':21136,'chunks':23}],'initial_sync_state':1,'post_start_sync_state':3,'sync_CPU_address':'0x180c1140','sync_mask':'0xe'},'checks':{'actual_OEM_ARM_patch_contract':23,'actual_OEM_ARM_main_contract':27,'actual_OEM_ARM_download_mode':15,'actual_OEM_ARM_runtime_query':8,'actual_C_core_ASan_UBSan':99,'QEMU_command_checks':qemu,'actual_ARM_decompressor':6,'actual_ARM_handoff':5,'actual_ARM_restart':8,'ELF_ABI_closure':57,'Linux_patch_files_apply_exact':20,'new_build_compiled_and_verified':True},'source_scope':'evidence/ram6-change-scope.json','rootfs_firmware_scope':'Six exact generic user-supplied OEM blobs; FIRMWARE-SOURCES.json; no individual calibration','runtime_query':{'CID':'ed','extCID':'3c','query':0,'bytes':104,'category':5,'band':0,'count':1,'bitmap':1,'response_header':12,'counter_offset':8},'IRQ_mask_cleanup':{'zero_writes_only':True,'before_stop_and_after_all_control_restores':True,'strict_readback':True,'stage_snapshots':True},'not_proven':['physical runtime GET response and IRQ-mask restore','Wi-Fi IRQ','RF/calibration/AP/association','cold power equivalence','flash installation'],'cleanup':'Owned controls/GLO/writable4rings and explicit zero IRQmask restoration/readback; pin coherent pool if MCU/DMA stop fails','fresh_boot_required_after_attempt':True,'new_power_off_requested_for_next_test':False,'issued_parent_artifacts_immutable':True}
(r/'PROVENANCE.json').write_text(json.dumps(p,indent=2)+'\n')
(e/'script-result.json').write_text(json.dumps({'passed':True,'records':records,'script_bytes':p['script_bytes'],'unchanged_hardware_confirmed_runner':True},indent=2)+'\n')
readme='# OpenWrt RAM7: запрос к основному MCU и очистка IRQ mask\n\nRAM6 аппаратно завершила full main download:3области/25616B/29chunks,\nstart ACK0 и рабочее состояние MCU3. Итог16 относился к cleanup: mask\nизменилась с0 на20000000. DMAidle/MCUstopped/GLO/owned/rings были исправны.\nRAM7 явно восстанавливает0 в IRQmask и запрашивает один счётчик у main MCU.\nЭто новая аппаратная проверка; готовность точки доступа не заявляется.\n\n## Пять файлов в TFTP\n\nСкопируйте в корень TFTP c80-script-runner.bin, новый c80-start.txt\n(заменить прежний) и три файла из таблицы. ПК оставьтеLAN1/192.168.0.3/24.\n\n|Файл|Байт|CRC32|\n|---|---:|---|\n'+''.join(f"|{x['file']}|{x['bytes']}|{x['crc32']}|\n" for x in records)+'\n## Из текущего OpenWrt\n\nВыполните `reboot`, остановите Autoboot до `MT7626>`. Дополнительное\nфизическое отключение питания сейчас не требуется. В U-Boot по одной:\n\n```text\nsetenv autostart no\ntftpboot 40280000 c80-script-runner.bin\n```\n\nТолько после успешной передачи4732B:\n\n```text\ngo 40280000\n```\n\nПомощник проверит размеры/CRC и загрузит ядро6.12.113-c80-openwrt-ram7-query.\nВ новом OpenWrt вводите короткие команды по одной с ожиданием prompt,\nне вставляйте блок сразу (polling UART терял окончания длинных строк):\n\n```sh\nuname -r\ncd /sys/kernel\ncd c80_wifi\ncat status\n```\n\nЕсли ran=0/finished=0, отдельно:\n\n```sh\necho 1 > run\n```\n\nДождитесь prompt, затем отдельно:\n\n```sh\ncat status\nfree\n```\n\nПришлите весь вывод uname→free со стадиями ядра; оставайтесь в OpenWrt.\nПовторный run не нужен; guards не обходить.\n\n## Ожидаемый результат\n\nResult/primary/cleanup/critical0. Прежний main по-прежнему3/3, bytes25616/\nchunks29, startvalid1/status0/ready1, sync raw6. Затем runtime_glo_after\nбез bit200, counter_query_attempted1/valid1/category5/count1. Значение\nсчётчика произвольное, включая0; это не код ошибки.\n\nСо свежим patch ожидаются TX41/41=command10/10+FWDL31/31, RX10, EIDed/\next3c/sequence11. При первомpatch-ready1 — TX35/RX6/sequence5. Query не\nотправляется до подтверждённого main ready или при отказе mode-off readback.\n\nCleanup: DMAidle1/MCUstopped1/pools_retained0, GLO10001870/IRQmask0,\ncleanup_flags/owned_bad/rings_bad0. Все writable4ring controls восстановлены.\nIRQmask записывается только0 перед stop и последней операцией после\nвосстановления controls; нулевой readback проверяется, отказ остаётся16.\nСтрока mask_at_ready/runtime/cleanup_entry/first_zero/after_stop/before_final\nсохраняет точные наблюдения изменения. Bit20000000 не скрывается из сравнения.\n\nНовый код24 — неверная структура query ответа;13 — RX timeout,12 — TX\ntimeout;23 — DMA mode refusal. Таймаут даёт pre-cleanup failure snapshot.\nMain1/query0 с ошибкой не считается полным pass. Fresh boot после опыта\nобязателен; критические80/81 по-прежнему закрепляют coherent pool.\n\n## Что изменено и проверено\n\nТолько два MCU source файла в полном Linux tree, rootfs прежний побайтно.\nRuntime GET восстановлен по настоящему OEM builder40314588/header4026249c/\nextended dispatcher и callback4030f1e0; mask0 write по OEM IRQ-disable.\nКонтракт и точные пакеты — evidence/runtime-query-contract.md и\nstock-query-traces.json. Это запрос счётчика, не проверка линии Wi-Fi IRQ\nCPU, не включение RF/AP/MAC TX/RX и не загрузка индивидуальных калибровок.\n\n99actualC ASan/UBSan сценариев с40OEM packet oracle;8новых actualOEMARM\nсценариев. Прежние15mode/27main/23patch ARM evidence неизменны. Новая сборка\nпрошла33+31 QEMU проверки actual userspace/sysfs/refusal/reboot,6ARM\ndecompressor/5handoff/8restart,57ELF/fullCPIO/compiledDTB/config/RAMbounds\nи20-fileLinuxpatch. QEMU не эмулирует C80/MCU; аппаратные ответы в моделях\nсинтетические. Физический runtime query и маска теперь требуют проверки.\n\nСохраняются6точных generic OEM firmware файлов/CRC до MMIO,2MiB no-map\nEMI, once-per-boot, bounded waits, strict stop/restore. Нет IRQ-enable/GIC/\nflash записей. Преднамеренно останавливаем MCU после опыта, main_ready\nозначает готовность до cleanup; Wi-Fi AP ещё не настроена. NOR read-only;\nсистема и настройки временные вRAM. После reboot образ загрузить заново.\n\nВсе выданные RAM6 файлы/ZIP сохранены; diff — ram6-to-ram7.patch.\nИндивидуальные калибровки/MAC/пароли, полный TPOS/U-Boot/NOR не включены.\nOEM лицензии сохранены, общие права распространения не заявляются.\n'
(r/'README.md').write_text(readme)
print(json.dumps({'load_files':records,'checks':p['checks'],'script_bytes':p['script_bytes']},indent=2))
